// viewerScopedSeed is the shared fixture for the viewer-scoped read tests:
// two libraries (granted A, hidden B), one series row and one episode item in
// each. The granted viewer sees only the A world; every hidden-B fact is
// asserted invisible — rows, not-found identities, and episode listings.
type viewerScopedSeed struct {
	libA, libB       int64
	seriesA, seriesB Series
}

// seedViewerWorld creates the two-library world. It must run through the
// all-seeing scope: the seed itself is not a viewer concern.
func seedViewerWorld(t *testing.T, s *Store) viewerScopedSeed {
	t.Helper()
	ctx := context.Background()
	sys := access.System()

	libA, err := s.CreateLibrary(ctx, "serial", "/data/viewer-a", "Granted")
	if err != nil {
		t.Fatalf("CreateLibrary A: %v", err)
	}
	libB, err := s.CreateLibrary(ctx, "serial", "/data/viewer-b", "Hidden")
	if err != nil {
		t.Fatalf("CreateLibrary B: %v", err)
	}

	putSeries := func(lib int64, rel string) Series {
		if err := s.PutSeries(ctx, Series{
			ModuleID: "serial", LibraryID: lib, RelativePath: rel,
			Document: json.RawMessage(`{}`), SchemaVersion: 1, Status: "ready",
		}); err != nil {
			t.Fatalf("PutSeries %s: %v", rel, err)
		}
		sr, err := s.GetSeriesByPath(ctx, lib, rel, sys)
		if err != nil {
			t.Fatalf("GetSeriesByPath %s: %v", rel, err)
		}
		return sr
	}
	seriesA := putSeries(libA, "Show.A")
	seriesB := putSeries(libB, "Show.B")

	putItem := func(lib int64, rel string) {
		if err := s.PutItem(ctx, Item{
			ID: rel, ModuleID: "serial", LibraryID: lib, FileID: rel,
			RelativePath: rel, MediaType: "episode",
			Document: json.RawMessage(`{}`), SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", rel, err)
		}
	}
	putItem(libA, "Show.A/ep1.mkv")
	putItem(libB, "Show.B/ep1.mkv")

	return viewerScopedSeed{libA: libA, libB: libB, seriesA: seriesA, seriesB: seriesB}
}

// TestLibraryReadsViewerScoped pins 4.2's library-read contract: a scoped user
// sees ONLY its granted libraries (hidden ≡ not-found from every get read),
// the empty-grant and zero viewers fail closed (200-empty for lists,
// not-found for gets), and the see-all viewers (System/Admin/LegacyDevice)
// keep the byte-identical unfiltered behavior.
func TestLibraryReadsViewerScoped(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	vUser := access.User(1, []int64{seed.libA}, nil)

	t.Run("list_libraries_granted_only", func(t *testing.T) {
		libs, err := s.ListLibraries(ctx, vUser)
		if err != nil {
			t.Fatalf("ListLibraries(user): %v", err)
		}
		if len(libs) != 1 || libs[0].ID != seed.libA {
			t.Fatalf("ListLibraries(user) = %+v, want only library %d", libs, seed.libA)
		}
	})

	t.Run("empty_grant_fails_closed_200_empty", func(t *testing.T) {
		libs, err := s.ListLibraries(ctx, access.User(2, nil, nil))
		if err != nil {
			t.Fatalf("ListLibraries(empty user): %v", err)
		}
		if libs == nil || len(libs) != 0 {
			t.Fatalf("ListLibraries(empty user) = %#v, want non-nil empty slice", libs)
		}
	})

	t.Run("zero_viewer_fails_closed_200_empty", func(t *testing.T) {
		libs, err := s.ListLibraries(ctx, access.Viewer{})
		if err != nil {
			t.Fatalf("ListLibraries(zero): %v", err)
		}
		if libs == nil || len(libs) != 0 {
			t.Fatalf("ListLibraries(zero) = %#v, want non-nil empty slice", libs)
		}
	})

	t.Run("see_all_viewers_unfiltered", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"system": access.System(), "admin": access.Admin(), "legacy": access.LegacyDevice(),
		} {
			libs, err := s.ListLibraries(ctx, v)
			if err != nil {
				t.Fatalf("ListLibraries(%s): %v", name, err)
			}
			if len(libs) != 2 {
				t.Fatalf("ListLibraries(%s) = %d rows, want 2 (zero-row-loss)", name, len(libs))
			}
		}
	})

	t.Run("hidden_library_reads_as_not_found", func(t *testing.T) {
		if _, err := s.GetLibrary(ctx, seed.libB, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetLibrary(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		if _, _, err := s.LibrarySummary(ctx, seed.libB, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("LibrarySummary(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		if _, err := s.LibraryFolders(ctx, seed.libB, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("LibraryFolders(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		// Hidden is only for the scoped viewer: the row still exists for System.
		if _, err := s.GetLibrary(ctx, seed.libB, access.System()); err != nil {
			t.Fatalf("GetLibrary(hidden, system): %v", err)
		}
	})

	t.Run("granted_library_reads_succeed", func(t *testing.T) {
		lib, err := s.GetLibrary(ctx, seed.libA, vUser)
		if err != nil {
			t.Fatalf("GetLibrary(granted): %v", err)
		}
		if lib.ID != seed.libA {
			t.Fatalf("GetLibrary(granted).ID = %d, want %d", lib.ID, seed.libA)
		}
		items, updated, err := s.LibrarySummary(ctx, seed.libA, vUser)
		if err != nil {
			t.Fatalf("LibrarySummary(granted): %v", err)
		}
		if items != 1 {
			t.Fatalf("LibrarySummary(granted) items = %d, want 1", items)
		}
		if updated == "" {
			t.Fatalf("LibrarySummary(granted) updatedAt = \"\", want the item's stamp")
		}
		folders, err := s.LibraryFolders(ctx, seed.libA, vUser)
		if err != nil {
			t.Fatalf("LibraryFolders(granted): %v", err)
		}
		if len(folders) != 1 || folders[0].Path != "Show.A" || folders[0].Items != 1 {
			t.Fatalf("LibraryFolders(granted) = %+v, want [Show.A:1]", folders)
		}
	})
}

// TestSeriesReadsViewerScoped pins 4.2's series-read contract: a scoped user's
// series reads surface only rows (and episode items) inside the granted
// libraries — a hidden library's series reads exactly like a missing row, its
// episodes list empty, and the orphan case (a series living in a non-granted
// library) is invisible even when handed to QueryItemsBySeries directly.
func TestSeriesReadsViewerScoped(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	vUser := access.User(1, []int64{seed.libA}, nil)

	t.Run("query_series_granted_only", func(t *testing.T) {
		rows, err := s.QuerySeries(ctx, seed.libA, "", vUser)
		if err != nil {
			t.Fatalf("QuerySeries(granted): %v", err)
		}
		if len(rows) != 1 || rows[0].ID != seed.seriesA.ID {
			t.Fatalf("QuerySeries(granted) = %+v, want only %s", rows, seed.seriesA.ID)
		}
		hidden, err := s.QuerySeries(ctx, seed.libB, "", vUser)
		if err != nil {
			t.Fatalf("QuerySeries(hidden): %v", err)
		}
		if hidden == nil || len(hidden) != 0 {
			t.Fatalf("QuerySeries(hidden) = %#v, want non-nil empty slice", hidden)
		}
	})

	t.Run("empty_grant_and_zero_viewer_see_nothing", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"empty_user": access.User(2, nil, nil),
			"zero":       {},
		} {
			rows, err := s.QuerySeries(ctx, seed.libA, "", v)
			if err != nil {
				t.Fatalf("QuerySeries(%s): %v", name, err)
			}
			if rows == nil || len(rows) != 0 {
				t.Fatalf("QuerySeries(%s) = %#v, want non-nil empty slice", name, rows)
			}
			ids, err := s.ListSeriesIDs(ctx, seed.libA, v)
			if err != nil {
				t.Fatalf("ListSeriesIDs(%s): %v", name, err)
			}
			if ids == nil || len(ids) != 0 {
				t.Fatalf("ListSeriesIDs(%s) = %#v, want non-nil empty slice", name, ids)
			}
		}
	})

	t.Run("hidden_series_reads_as_not_found", func(t *testing.T) {
		if _, err := s.GetSeries(ctx, seed.seriesB.ID, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetSeries(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		if _, err := s.GetSeriesByPath(ctx, seed.libB, "Show.B", vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetSeriesByPath(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		// Hidden is only for the scoped viewer: System reads the row (and its
		// id list) unchanged.
		if _, err := s.GetSeries(ctx, seed.seriesB.ID, access.System()); err != nil {
			t.Fatalf("GetSeries(hidden, system): %v", err)
		}
		ids, err := s.ListSeriesIDs(ctx, seed.libB, access.System())
		if err != nil {
			t.Fatalf("ListSeriesIDs(hidden, system): %v", err)
		}
		if len(ids) != 1 {
			t.Fatalf("ListSeriesIDs(hidden, system) = %v, want 1 id (zero-row-loss)", ids)
		}
	})

	t.Run("granted_series_reads_succeed", func(t *testing.T) {
		sr, err := s.GetSeries(ctx, seed.seriesA.ID, vUser)
		if err != nil {
			t.Fatalf("GetSeries(granted): %v", err)
		}
		if sr.ID != seed.seriesA.ID {
			t.Fatalf("GetSeries(granted).ID = %s, want %s", sr.ID, seed.seriesA.ID)
		}
		byPath, err := s.GetSeriesByPath(ctx, seed.libA, "Show.A", vUser)
		if err != nil {
			t.Fatalf("GetSeriesByPath(granted): %v", err)
		}
		if byPath.ID != seed.seriesA.ID {
			t.Fatalf("GetSeriesByPath(granted).ID = %s, want %s", byPath.ID, seed.seriesA.ID)
		}
		ids, err := s.ListSeriesIDs(ctx, seed.libA, vUser)
		if err != nil {
			t.Fatalf("ListSeriesIDs(granted): %v", err)
		}
		if len(ids) != 1 || ids[0] != seed.seriesA.ID {
			t.Fatalf("ListSeriesIDs(granted) = %v, want [%s]", ids, seed.seriesA.ID)
		}
	})

	t.Run("episodes_scoped_and_orphan_invisible", func(t *testing.T) {
		eps, err := s.QueryItemsBySeries(ctx, seed.seriesA, SeriesBackingDirectory, vUser)
		if err != nil {
			t.Fatalf("QueryItemsBySeries(granted): %v", err)
		}
		if len(eps) != 1 || eps[0].RelativePath != "Show.A/ep1.mkv" {
			t.Fatalf("QueryItemsBySeries(granted) = %+v, want the one granted episode", eps)
		}
		// The orphan case: the series row AND its episodes sit in the
		// non-granted library — the listing is empty, never a leak, even with
		// the hidden series row handed in directly.
		orphan, err := s.QueryItemsBySeries(ctx, seed.seriesB, SeriesBackingDirectory, vUser)
		if err != nil {
			t.Fatalf("QueryItemsBySeries(orphan): %v", err)
		}
		if orphan == nil || len(orphan) != 0 {
			t.Fatalf("QueryItemsBySeries(orphan) = %#v, want non-nil empty slice (no leak)", orphan)
		}
		// System still sees the hidden library's episode (zero-row-loss).
		sysEps, err := s.QueryItemsBySeries(ctx, seed.seriesB, SeriesBackingDirectory, access.System())
		if err != nil {
			t.Fatalf("QueryItemsBySeries(orphan, system): %v", err)
		}
		if len(sysEps) != 1 {
			t.Fatalf("QueryItemsBySeries(orphan, system) = %+v, want 1 episode", sysEps)
		}
	})
}

// TestItemReadsViewerScoped pins 4.3's item-read contract: a scoped user's
// QueryItems window holds only granted-library rows (empty grants and the
// zero viewer fail closed to the 200-empty shape), a hidden item reads exactly
// like a missing row from GetItem — and reads exactly as unknown to a scoped
// PutProgress writer, whose visibility-guarded existence check then writes
// nothing — while the see-all viewers keep the unfiltered behavior.
func TestItemReadsViewerScoped(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	vUser := access.User(1, []int64{seed.libA}, nil)
	grantedID, hiddenID := "Show.A/ep1.mkv", "Show.B/ep1.mkv"

	t.Run("query_items_granted_only", func(t *testing.T) {
		items, err := s.QueryItems(ctx, seed.libA, "", "", false, 100, 0, vUser)
		if err != nil {
			t.Fatalf("QueryItems(granted): %v", err)
		}
		if len(items) != 1 || items[0].ID != grantedID {
			t.Fatalf("QueryItems(granted) = %+v, want only %s", items, grantedID)
		}
		// The hidden library's own window is empty for this viewer — the
		// 200-empty listing shape, never an error, never a leak.
		hidden, err := s.QueryItems(ctx, seed.libB, "", "", false, 100, 0, vUser)
		if err != nil {
			t.Fatalf("QueryItems(hidden lib): %v", err)
		}
		if hidden == nil || len(hidden) != 0 {
			t.Fatalf("QueryItems(hidden lib) = %#v, want non-nil empty slice", hidden)
		}
	})

	t.Run("empty_grant_and_zero_viewer_see_nothing", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"empty_user": access.User(2, nil, nil),
			"zero":       {},
		} {
			items, err := s.QueryItems(ctx, seed.libA, "", "", false, 100, 0, v)
			if err != nil {
				t.Fatalf("QueryItems(%s): %v", name, err)
			}
			if items == nil || len(items) != 0 {
				t.Fatalf("QueryItems(%s) = %#v, want non-nil empty slice", name, items)
			}
		}
	})

	t.Run("see_all_viewers_unfiltered", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"system": access.System(), "admin": access.Admin(), "legacy": access.LegacyDevice(),
		} {
			for libName, lib := range map[string]int64{"granted": seed.libA, "hidden": seed.libB} {
				items, err := s.QueryItems(ctx, lib, "", "", false, 100, 0, v)
				if err != nil {
					t.Fatalf("QueryItems(%s, %s): %v", name, libName, err)
				}
				if len(items) != 1 {
					t.Fatalf("QueryItems(%s, %s) = %d rows, want 1 (zero-row-loss)", name, libName, len(items))
				}
			}
		}
	})

	t.Run("hidden_item_reads_as_not_found", func(t *testing.T) {
		if _, err := s.GetItem(ctx, hiddenID, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetItem(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		it, err := s.GetItem(ctx, grantedID, vUser)
		if err != nil {
			t.Fatalf("GetItem(granted): %v", err)
		}
		if it.ID != grantedID {
			t.Fatalf("GetItem(granted).ID = %s, want %s", it.ID, grantedID)
		}
		// Hidden is only for the scoped viewer: System reads the row unchanged.
		if _, err := s.GetItem(ctx, hiddenID, access.System()); err != nil {
			t.Fatalf("GetItem(hidden, system): %v", err)
		}
	})

	t.Run("put_progress_hidden_item_unknown", func(t *testing.T) {
		// A scoped writer against a hidden item: the existence check treats it
		// as missing (wrapped sql.ErrNoRows) and NOTHING is written.
		if _, err := s.PutProgress(ctx, hiddenID, 60, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("PutProgress(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		if _, err := s.GetProgress(ctx, hiddenID, access.System()); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetProgress(hidden after scoped put) = %v, want wrapped sql.ErrNoRows (nothing written)", err)
		}
		// The granted item writes fine for the same viewer.
		if _, err := s.PutProgress(ctx, grantedID, 60, vUser); err != nil {
			t.Fatalf("PutProgress(granted): %v", err)
		}
		got, err := s.GetProgress(ctx, grantedID, access.System())
		if err != nil {
			t.Fatalf("GetProgress(granted): %v", err)
		}
		if got.PositionSeconds != 60 {
			t.Fatalf("GetProgress(granted).PositionSeconds = %d, want 60", got.PositionSeconds)
		}
	})
}

// TestParserReadsViewerScoped pins 4.3's parser-read contract: ListItemParsers
// rides its item/library join, so a scoped user lists parsers only for items
// inside the granted libraries — a hidden item's attachments are invisible
// even when handed the item id directly (the orphan-tolerant empty slice) —
// and System keeps seeing every attachment.
func TestParserReadsViewerScoped(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	vUser := access.User(1, []int64{seed.libA}, nil)
	grantedID, hiddenID := "Show.A/ep1.mkv", "Show.B/ep1.mkv"

	// Attachments are writes, not reads: the seeding runs System-side.
	if err := s.SetItemParsers(ctx, grantedID, []string{"chain.first", "footer.a"}); err != nil {
		t.Fatalf("SetItemParsers(granted): %v", err)
	}
	if err := s.SetItemParsers(ctx, hiddenID, []string{"chain.first"}); err != nil {
		t.Fatalf("SetItemParsers(hidden): %v", err)
	}

	t.Run("granted_item_parsers_listed", func(t *testing.T) {
		got, err := s.ListItemParsers(ctx, grantedID, vUser)
		if err != nil {
			t.Fatalf("ListItemParsers(granted): %v", err)
		}
		if len(got) != 2 || got[0] != "chain.first" || got[1] != "footer.a" {
			t.Fatalf("ListItemParsers(granted) = %v, want [chain.first footer.a] in order", got)
		}
	})

	t.Run("hidden_item_parsers_invisible_by_id", func(t *testing.T) {
		got, err := s.ListItemParsers(ctx, hiddenID, vUser)
		if err != nil {
			t.Fatalf("ListItemParsers(hidden): %v", err)
		}
		if got == nil || len(got) != 0 {
			t.Fatalf("ListItemParsers(hidden) = %#v, want non-nil empty slice (no leak by direct id)", got)
		}
	})

	t.Run("empty_grant_and_zero_viewer_see_nothing", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"empty_user": access.User(2, nil, nil),
			"zero":       {},
		} {
			got, err := s.ListItemParsers(ctx, grantedID, v)
			if err != nil {
				t.Fatalf("ListItemParsers(%s): %v", name, err)
			}
			if got == nil || len(got) != 0 {
				t.Fatalf("ListItemParsers(%s) = %#v, want non-nil empty slice", name, got)
			}
		}
	})

	t.Run("system_sees_all", func(t *testing.T) {
		got, err := s.ListItemParsers(ctx, hiddenID, access.System())
		if err != nil {
			t.Fatalf("ListItemParsers(hidden, system): %v", err)
		}
		if len(got) != 1 || got[0] != "chain.first" {
			t.Fatalf("ListItemParsers(hidden, system) = %v, want [chain.first] (zero-row-loss)", got)
		}
	})
}

// TestProgressReadsViewerScoped pins 4.4's progress-read contract: a scoped
// user's ListProgress window holds only rows BOTH in its own ledger slot AND
// in a granted library, with the conjuncts filtered BEFORE the limit window
// (a small window still fills with readable rows — hidden or foreign-slot
// newer rows never displace them), a hidden item's stored position reads
// exactly as absent from GetProgress (hidden ≡ not-found), the empty-grant
// and zero viewers fail closed to the 200-empty shape — and System, the
// boot-backfill read, still sees EVERY row: both libraries and all three
// ledger slots, the learning invariant (design D7).
//
// Slot-semantics boundary (5.2): the granted seeds land in user 1's OWN slot
// so the scoped viewer reads them; the foreign slots (0 legacy + user 5) on
// the same granted item exist to prove the OWN-SLOT conjunct — user 1's
// window skips the slot-5 row even though its library is granted — and so
// System's all-seeing read is proven over every slot.
func TestProgressReadsViewerScoped(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	vUser := access.User(1, []int64{seed.libA}, nil)
	grantedID, hiddenID := "Show.A/ep1.mkv", "Show.B/ep1.mkv"

	// Two more items per side give the window test real order pressure.
	putItem := func(lib int64, rel string) {
		if err := s.PutItem(ctx, Item{
			ID: rel, ModuleID: "serial", LibraryID: lib, FileID: rel,
			RelativePath: rel, MediaType: "episode",
			Document: json.RawMessage(`{}`), SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", rel, err)
		}
	}
	putItem(seed.libA, "Show.A/ep2.mkv")
	putItem(seed.libB, "Show.B/ep2.mkv")
	putItem(seed.libB, "Show.B/ep3.mkv")

	// Rows land via direct SQL (a write seed, System-side by construction) so
	// the stamps are controlled: every HIDDEN row is NEWER than every granted
	// row — the exact shape where filtering after the limit window would fill
	// the window with hidden rows. The granted rows stamp user 1's slot (the
	// scoped viewer's own slot below).
	seedProgress := func(itemID string, pos int64, at string, userID int64) {
		if _, err := s.db.ExecContext(ctx,
			"INSERT INTO playback_progress (user_id, item_id, position_seconds, updated_at) VALUES (?, ?, ?, ?)",
			userID, itemID, pos, at); err != nil {
			t.Fatalf("seed progress %s (slot %d): %v", itemID, userID, err)
		}
	}
	seedProgress(hiddenID, 40, "2026-03-05T00:00:00Z", 0)
	seedProgress("Show.B/ep2.mkv", 41, "2026-03-04T00:00:00Z", 0)
	seedProgress("Show.B/ep3.mkv", 42, "2026-03-03T00:00:00Z", 0)
	seedProgress(grantedID, 60, "2026-03-02T00:00:00Z", 1)
	seedProgress("Show.A/ep2.mkv", 61, "2026-03-01T00:00:00Z", 1)
	// A FOREIGN slot for the granted item, stamped OLDEST: the own-slot
	// conjunct's proof material — user 1's window skips it (its slot is 5),
	// and System's all-seeing read proves the row rode in (three slots
	// covered: 0 legacy, 1 scoped user, 5 foreign user).
	seedProgress(grantedID, 70, "2026-02-20T00:00:00Z", 5)

	t.Run("list_progress_granted_only", func(t *testing.T) {
		got, err := s.ListProgress(ctx, 10, vUser)
		if err != nil {
			t.Fatalf("ListProgress(user): %v", err)
		}
		// Own slot + granted library only: the slot-5 row on the granted item
		// is invisible (own-slot), as is every hidden-library row (conjunct).
		wantPos := []int64{60, 61}
		if len(got) != len(wantPos) {
			t.Fatalf("ListProgress(user) = %d rows, want %d (own slot, granted library only)", len(got), len(wantPos))
		}
		for i, r := range got {
			if r.ItemID != grantedID && r.ItemID != "Show.A/ep2.mkv" {
				t.Fatalf("ListProgress(user)[%d] = %s, want only granted-library items", i, r.ItemID)
			}
			if r.PositionSeconds != wantPos[i] {
				t.Fatalf("ListProgress(user)[%d].PositionSeconds = %d, want %d (newest-first)", i, r.PositionSeconds, wantPos[i])
			}
		}
	})

	t.Run("filtered_before_limit", func(t *testing.T) {
		// The three hidden rows are the three NEWEST rows overall: an
		// unfiltered LIMIT 2 window would hold two hidden rows. The window
		// returning the two granted rows proves the conjunct filtered before
		// the window filled.
		got, err := s.ListProgress(ctx, 2, vUser)
		if err != nil {
			t.Fatalf("ListProgress(user, 2): %v", err)
		}
		if len(got) != 2 || got[0].ItemID != grantedID || got[1].ItemID != "Show.A/ep2.mkv" {
			names := make([]string, len(got))
			for i, r := range got {
				names[i] = r.ItemID
			}
			t.Fatalf("ListProgress(user, 2) = %v, want [%s Show.A/ep2.mkv] (filter-before-limit)", names, grantedID)
		}
	})

	t.Run("hidden_progress_reads_as_not_found", func(t *testing.T) {
		if _, err := s.GetProgress(ctx, hiddenID, vUser); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetProgress(hidden) = %v, want wrapped sql.ErrNoRows", err)
		}
		got, err := s.GetProgress(ctx, grantedID, vUser)
		if err != nil {
			t.Fatalf("GetProgress(granted): %v", err)
		}
		if got.PositionSeconds != 60 {
			t.Fatalf("GetProgress(granted).PositionSeconds = %d, want 60", got.PositionSeconds)
		}
		// Hidden is only for the scoped viewer: System reads the row unchanged.
		if _, err := s.GetProgress(ctx, hiddenID, access.System()); err != nil {
			t.Fatalf("GetProgress(hidden, system): %v", err)
		}
	})

	t.Run("empty_grant_and_zero_viewer_see_nothing", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"empty_user": access.User(2, nil, nil),
			"zero":       {},
		} {
			got, err := s.ListProgress(ctx, 10, v)
			if err != nil {
				t.Fatalf("ListProgress(%s): %v", name, err)
			}
			if got == nil || len(got) != 0 {
				t.Fatalf("ListProgress(%s) = %#v, want non-nil empty slice", name, got)
			}
			all, err := s.ListProgressAll(ctx, v)
			if err != nil {
				t.Fatalf("ListProgressAll(%s): %v", name, err)
			}
			if all == nil || len(all) != 0 {
				t.Fatalf("ListProgressAll(%s) = %#v, want non-nil empty slice", name, all)
			}
			if _, err := s.GetProgress(ctx, grantedID, v); !errors.Is(err, sql.ErrNoRows) {
				t.Fatalf("GetProgress(%s) = %v, want wrapped sql.ErrNoRows", name, err)
			}
		}
	})

	t.Run("system_backfill_sees_all_libraries_and_slots", func(t *testing.T) {
		all, err := s.ListProgressAll(ctx, access.System())
		if err != nil {
			t.Fatalf("ListProgressAll(system): %v", err)
		}
		// Six rows: three hidden-library rows, the granted item in BOTH of its
		// foreign-visible slots (user 1 + user 5), and the second granted item
		// (user 1's slot) — nothing dropped, any slot, any library.
		if len(all) != 6 {
			names := make([]string, len(all))
			for i, r := range all {
				names[i] = r.ItemID
			}
			t.Fatalf("ListProgressAll(system) = %d rows %v, want 6 (all libraries, all slots)", len(all), names)
		}
		// The unbounded read's newest-first head is the newest hidden row, and
		// the granted item surfaces in BOTH slots — proving every slot rode in.
		if all[0].ItemID != hiddenID {
			t.Fatalf("ListProgressAll(system)[0] = %+v, want the newest hidden row", all[0])
		}
		grantedSlots := 0
		for _, r := range all {
			if r.ItemID == grantedID {
				grantedSlots++
			}
		}
		if grantedSlots != 2 {
			t.Fatalf("ListProgressAll(system) holds %d rows for %s, want 2 (user slot 1 + user slot 5)", grantedSlots, grantedID)
		}
		hidden := map[string]bool{}
		for _, r := range all {
			hidden[r.ItemID] = true
		}
		for _, id := range []string{hiddenID, "Show.B/ep2.mkv", "Show.B/ep3.mkv"} {
			if !hidden[id] {
				t.Fatalf("ListProgressAll(system) missing hidden-library row %s (zero-row-loss)", id)
			}
		}
	})
}
